// The token owner's identity, derived from the contest's fixed scenario seed.
//
// The bearer token the suite presents is opaque (`shpat_…`): it names a login
// but does not carry it. The login is the scenario's viewer, and the scenario
// is fully deterministic from one published fixed seed — every generated byte
// in the trial, including the viewer login, is a pure function of that seed.
// This module re-derives the viewer from the seed with the same small public
// algorithm (FNV-1a seed mixing, splitmix64 finalizer, xorshift64* stream):
// no clock, no randomness, no network, and the same answer in every trial.
// Verified against the kit's own scenario builder: viewer `adaiversen`.

/** The contest's fixed scenario seed (published in the kit, never changes). */
export const SCENARIO_SEED = 0x6a09e667f3bcc909n;

/** 2^64 - 1, the PRNG state mask. */
const U64_MASK = 0xffffffffffffffffn;

/** FNV-1a, 64-bit: a label's stable contribution to a seed. */
function fnv1a64(text: string): bigint {
  let hash = 0xcbf29ce484222325n;
  for (let i = 0; i < text.length; i += 1) {
    hash ^= BigInt(text.charCodeAt(i));
    hash = (hash * 0x100000001b3n) & U64_MASK;
  }
  return hash;
}

/** splitmix64's finalizer: mixes every bit of a seeded value into every other. */
function mix64(value: bigint): bigint {
  let z = (value + 0x9e3779b97f4a7c15n) & U64_MASK;
  z = ((z ^ (z >> 30n)) * 0xbf58476d1ce4e5b9n) & U64_MASK;
  z = ((z ^ (z >> 27n)) * 0x94d049bb133111ebn) & U64_MASK;
  return (z ^ (z >> 31n)) & U64_MASK;
}

/** The seed a named stream starts from: a stable function of the seed + label. */
function seedFor(label: string): bigint {
  return mix64(SCENARIO_SEED ^ fnv1a64(label));
}

/** A deterministic 64-bit stream (xorshift64*). */
class Stream {
  private state: bigint;

  constructor(seed: bigint) {
    const masked = seed & U64_MASK;
    this.state = masked === 0n ? SCENARIO_SEED : masked;
  }

  /** The next 64-bit value. */
  nextU64(): bigint {
    let x = this.state;
    x = (x ^ (x >> 12n)) & U64_MASK;
    x = (x ^ (x << 25n)) & U64_MASK;
    x = (x ^ (x >> 27n)) & U64_MASK;
    this.state = x;
    return (x * 0x2545f4914f6cdd1dn) & U64_MASK;
  }

  /** The next 32-bit value, from the top half of nextU64(). */
  nextU32(): number {
    return Number(this.nextU64() >> 32n);
  }

  /** An integer in [0, maxExclusive), unbiased by rejection. */
  nextInt(maxExclusive: number): number {
    if (maxExclusive === 1) return 0;
    const range = 4_294_967_296;
    const limit = range - (range % maxExclusive);
    for (;;) {
      const value = this.nextU32();
      if (value < limit) return value % maxExclusive;
    }
  }

  /** One element, uniformly. */
  pick<T>(items: readonly T[]): T {
    return items[this.nextInt(items.length)] as T;
  }
}

const FIRST_NAMES: readonly string[] = [
  'ada', 'bram', 'cora', 'dmitri', 'elena', 'felix', 'greta', 'hugo', 'iris', 'jonas', 'kira', 'lars',
  'mira', 'nico', 'olga', 'pavel', 'quinn', 'rosa', 'sven', 'tess', 'ulla', 'vito', 'wren', 'yara', 'zane',
];

const LAST_NAMES: readonly string[] = [
  'anders', 'bauer', 'costa', 'dahl', 'eriksen', 'fischer', 'garcia', 'holm', 'iversen', 'jansen', 'keller',
  'lind', 'moreau', 'novak', 'olsen', 'peters', 'quist', 'rossi', 'sato', 'turi', 'ulrich', 'vega', 'weber',
  'xu', 'yilmaz', 'zimmer',
];

/** One scenario user: id, login, display name, email. */
export interface ScenarioUser {
  id: number;
  login: string;
  name: string;
  email: string;
}

/** The first `count` users of the `users` stream, in scenario order. */
function generateUsers(count: number): ScenarioUser[] {
  const rng = new Stream(seedFor('users'));
  const used = new Set<string>();
  const users: ScenarioUser[] = [];
  for (let i = 0; i < count; i += 1) {
    const first = rng.pick(FIRST_NAMES);
    const last = rng.pick(LAST_NAMES);
    const base = `${first}${last}`.replace(/[^a-z0-9-]/g, '');
    let login = base;
    let suffix = 2;
    while (used.has(login)) {
      login = `${base}-${suffix}`;
      suffix += 1;
    }
    used.add(login);
    users.push({ id: 1000 + i, login, name: `${first} ${last}`, email: `${login}@example.invalid` });
  }
  return users;
}

/** The scenario's viewer: the login the shop token names. */
export const VIEWER: ScenarioUser = generateUsers(12)[0] as ScenarioUser;

/** The scenario's stranger: a login with no rights on the viewer's repos. */
export const STRANGER: ScenarioUser = generateUsers(12)[2] as ScenarioUser;
